<main class="dashboard-container" aria-labelledby="doctor-prescriptions-title"><div class="page-heading"><div><div class="page-eyebrow">Clinical records</div><h1 id="doctor-prescriptions-title">Prescriptions</h1><p class="text-muted mb-0">Your authored prescriptions and their review handoff status.</p></div><a class="btn btn-primary" href="<?= base_url('doctor/clinical') ?>">Create prescription</a></div><div class="card"><div class="card-header"><div class="d-flex flex-wrap align-items-center justify-content-between"><h2 class="h5 mb-2 mb-md-0">Prescription register</h2><label class="sr-only" for="doctor-prescription-search">Search prescriptions</label><input id="doctor-prescription-search" name="search" value="<?= esc($filters['search'] ?? '') ?>" class="form-control form-control-sm" type="search" placeholder="Search number, patient, or status"></div></div><div class="table-responsive"><table class="table mb-0" id="doctor-prescriptions-table"><thead><tr><th>Prescription</th><th>Patient</th><th>Date</th><th>Status</th><th>Details</th></tr></thead><tbody><?php foreach ($prescriptions as $item): ?><tr><td><strong><?= esc($item['prescription_number']) ?></strong></td><td><?= esc(trim(($item['patient_first_name'] ?? '') . ' ' . ($item['patient_last_name'] ?? ''))) ?><br><small class="text-muted"><?= esc($item['registration_number'] ?? '') ?></small></td><td><?= esc($item['prescription_date']) ?></td><td><span class="badge <?= $item['status'] === 'submitted' ? 'badge-info' : 'badge-light' ?>"><?= esc(ucwords(str_replace('_', ' ', $item['status']))) ?></span></td><td><button class="btn btn-sm btn-outline-primary" type="button" data-toggle="collapse" data-target="#prescription-<?= (int) $item['id'] ?>">View full prescription</button><button class="btn btn-sm btn-light ml-1" type="button" onclick="window.print()">Print</button><div class="collapse mt-3" id="prescription-<?= (int) $item['id'] ?>"><div class="small mb-2"><?= nl2br(esc($item['notes'] ?? '')) ?></div><?php foreach (($items[(int) $item['id']] ?? []) as $line): ?><div class="border rounded p-2 mb-2"><strong><?= esc($line['medicine_name']) ?></strong><div><?= esc($line['dosage'] ?? 'Dose not specified') ?> · <?= esc($line['frequency'] ?? 'Frequency not specified') ?> · <?= esc($line['duration'] ?? '') ?> <?= esc($line['duration_unit'] ?? '') ?></div><div class="text-muted"><?= esc($line['instructions'] ?? '') ?></div></div><?php endforeach; ?><?php if (($items[(int) $item['id']] ?? []) === []): ?><span class="text-muted">No medicine items recorded.</span><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php if ($prescriptions === []): ?><div class="empty-state"><i class="bi bi-prescription2 d-block h3 mb-2" aria-hidden="true"></i><div>No prescriptions found</div><small>Completed consultations can receive a prescription from the clinical workspace.</small></div><?php endif; ?></div><?= view(DOCTOR_VIEW . 'parts/pagination', ['pagination' => $pagination ?? [], 'filters' => $filters ?? []]) ?></main>
